import {loadTestSession} from './remote.mjs';
import {anchorSession} from './anchor-fixture.mjs';
import {normalizeTags,mountTags} from './tags.mjs';
import {sessions,timeLabel,rangeLabel,selection,samples,stats,transcripts,summary,draftKey,limitTheme} from './model.mjs';
let apiSession=null,apiError=null;
if(new URLSearchParams(location.search).get('test')==='1'){try{apiSession=await loadTestSession();sessions.push(apiSession);}catch(e){apiError=e.message;}}
if(anchorSession)sessions.push(anchorSession);
const $=id=>document.getElementById(id);let si=(apiSession||anchorSession)?sessions.length-1:0,top=0,step=600,index=null,cursor=0,playing=false,scope='range',drafts={},storageOK=true,lastTick=0;
try{const stored=JSON.parse(localStorage.getItem('diting-demo-reviews-v1')||'{}');if(stored&&typeof stored==='object'&&!Array.isArray(stored))drafts=stored;}catch{storageOK=false;}
const tagValues={keywords:[]};
$('session').replaceChildren(...sessions.map((s,i)=>{const o=document.createElement('option');o.value=i;o.textContent=`${s.teacher} · ${s.course}${s.source==='backend-test'?'（模拟联调）':s.source?'（真实测试）':'（模拟）'}`;return o;}));$('session').value=si;
const session=()=>sessions[si],bounds=()=>selection(session(),top,step,index),key=()=>draftKey(session().id,...bounds()),noteKey=()=>scope==='range'?key():`${session().id}:whole`;
function store(){try{localStorage.setItem('diting-demo-reviews-v1',JSON.stringify(drafts));storageOK=true;return true;}catch{storageOK=false;$('save-status').textContent='浏览器存储不可用，内容仅暂存本页';return false;}}
function persist(){const k=key(),n=noteKey();drafts[k]={...drafts[k],periodTheme:limitTheme($('theme').value),keywords:[...tagValues.keywords]};drafts[n]={...drafts[n],conclusion:$('conclusion').value,adjustment:$('adjustment').value};store();}
function edits(){const [a,b]=bounds();const generated=summary(session(),a,b);const value={...generated,...drafts[key()],theme:generated.theme};$('theme').value=typeof value.periodTheme==='string'?limitTheme(value.periodTheme):value.theme;updateThemeCount();for(const id of ['keywords']){tagValues[id]=normalizeTags(value[id]);mountTags($(id),tagValues[id],values=>{tagValues[id]=values;persist();$('save-status').textContent=storageOK?'标签已暂存 · 点击保存确认复盘':'浏览器存储不可用，标签仅暂存本页';});}const n=drafts[noteKey()]||{};$('conclusion').value=n.conclusion||'';$('adjustment').value=n.adjustment||'';$('draft-status').textContent=scope==='range'?rangeLabel(session(),a,b):'整场结论';$('save-status').textContent=!storageOK?'浏览器存储不可用':n.savedAt?`已保存 · ${new Date(n.savedAt).toLocaleTimeString('zh-CN')}`:'仅保存在当前浏览器';$('scope-range').setAttribute('aria-pressed',scope==='range');$('scope-session').setAttribute('aria-pressed',scope==='session');}
function tabs(){const s=session();$('session-meta').textContent=`${s.date}　${rangeLabel(s,0,s.duration)}`;$('top-tabs').replaceChildren();for(let i=0;i<Math.ceil(s.duration/1800);i++){const b=document.createElement('button');b.textContent=rangeLabel(s,i*1800,Math.min((i+1)*1800,s.duration));b.setAttribute('aria-selected',i===top);b.onclick=()=>change(()=>{top=i;index=null;cursor=i*1800});$('top-tabs').append(b);}}
function change(fn){persist();playing=false;fn();render();}
function render(){const s=session(),[a,b]=bounds();const real=['anchor-review','backend-test','backend-asr'].includes(s.source),remote=s.source==='backend-test';$('source-note').textContent=real?'主播后台真实快照 · 转写仅已加载片段 · 视频与实时采集未接入':'模拟数据测试 · 视频与文字均为演示';$('transcript-source').textContent=real?'平台原文 · 部分加载':'模拟文字 · 点击定位';$('video-note').textContent=real?'尚未接入本场录像':'模拟录屏回放';$('play').disabled=real;$('speed').disabled=real;$('theme').placeholder=real?'尚未生成，可手动填写':'';$('page-footer').textContent=real?'独立测试数据 · 复盘仅保存在当前浏览器':'全部为模拟数据 · 复盘仅保存在当前浏览器';$('session-aggregate').hidden=!s.aggregate;if(real&&s.aggregate){const m=s.aggregate;$('session-aggregate').textContent=`整场数据：平均在线 ${m.averageOnline} 人 · 最高 ${m.maximumOnline} 人 · 曝光约 ${m.exposureDisplay} · 进房 ${m.entries} 人 · 进房率 ${m.entryRatePercent}% · 人均停留 ${m.averageStayMinutes} 分钟 · 评论 ${m.commentUsers} 人 · 点赞 ${m.likes} 次 · 新增粉丝 ${m.newFollowers} 人 · 分享 ${m.shares} 次 · 加粉丝团 ${m.fanClubJoins} 人`;}cursor=Math.max(a,Math.min(cursor,b));tabs();$('chart-range').textContent=rangeLabel(s,a,b);
const end=Math.min((top+1)*1800,s.duration),num=Math.ceil((end-top*1800)/step);$('segment-slider').min=top*1800;$('segment-slider').max=end;$('segment-slider').step=1;$('segment-slider').value=cursor;$('segment-slider').setAttribute('aria-valuetext',index===null?'当前查看完整区间，拖动选择片段':rangeLabel(s,a,b));$('segment-buttons').replaceChildren();for(let i=0;i<num;i++){const button=document.createElement('button');const r=selection(s,top,step,i);button.textContent=rangeLabel(s,...r);button.setAttribute('aria-pressed',index===i);button.onclick=()=>change(()=>{index=i;cursor=r[0]});$('segment-buttons').append(button);}

const values=samples(s,a,b),st=stats(values);$('average').innerHTML=`${st.average??'—'}<small>人</small>`;$('maximum').innerHTML=`${st.max??'—'}<small>人</small>`;$('sample-count').innerHTML=`${st.count}<small>/ ${values.length} 点</small>`;$('chart-status').textContent=st.missing?`缺失 ${st.missing} 点 · 图中留空`:'每 10 秒采样 · 数据完整（模拟）';if(real&&!values.length){$('chart').replaceChildren();const empty=document.createElement('p');empty.className='chart-empty';empty.textContent='本时段在线人数曲线尚未采集';$('chart').append(empty);$('chart-status').textContent='整场均值和峰值不代表本时段曲线';$('hover-readout').textContent='';}else{renderChart(values,a,b);$('hover-readout').textContent='点击曲线定位回放';}
$('transcript').replaceChildren();for(const line of transcripts(s,a,b)){const button=document.createElement('button');button.dataset.t=line.t;const tm=document.createElement('time');tm.textContent=timeLabel(s,line.t,real);const tx=document.createElement('span');tx.textContent=`${s.teacher}：${line.text}`;button.append(tm,tx);button.onclick=()=>{cursor=line.t;playing=false;updateCursor();};$('transcript').append(button);}if(real){const note=document.createElement('p');note.className='muted';note.textContent=transcripts(s,a,b).length?'仅已加载 10:33:15—10:38:36 的 18 条记录，未覆盖完整时段':'本时段文字尚未加载';$('transcript').append(note);}edits();updateCursor();if(remote){$('source-note').textContent='模拟联调 · 数据从后端 PostgreSQL 读取';$('transcript-source').textContent='尚未接入 ASR';$('chart-status').textContent='模拟上传数据 · 每10秒采样';$('page-footer').textContent='独立模拟场次 · 曲线来自数据库 · 运营复盘仍存本浏览器';}if(s.source==='backend-asr'){$('source-note').textContent='真实ASR联调 · 淘宝录音样本 · 文字从PostgreSQL读取';$('transcript-source').textContent=s.processing?'ASR处理中':'公司ASR转写 · 音频块时间';$('transcript').querySelector('p.muted')?.remove();$('chart-status').textContent='未关联在线人数采样';$('page-footer').textContent='独立ASR测试 · 非本场直播数据';}if(apiError)$('source-note').textContent='联调读取失败：'+apiError;}
function renderChart(rows,a,b){const W=600,H=175,left=35,right=585,t=14,base=145;const max=Math.ceil(Math.max(100,...rows.map(r=>r.value??0))/50)*50,x=v=>left+(v-a)/(b-a)*(right-left),y=v=>base-v/max*(base-t);let lines='',active=false;for(const r of rows){if(r.value===null){active=false;continue;}lines+=`${active?'L':'M'}${x(r.t).toFixed(1)},${y(r.value).toFixed(1)} `;active=true;}
const grids=[0,.5,1].map(f=>`<line x1="${left}" x2="${right}" y1="${y(max*f)}" y2="${y(max*f)}" stroke="#e9eef6" stroke-dasharray="3 4"/><text x="25" y="${y(max*f)+4}" text-anchor="end" fill="#93a0b5" font-size="15">${max*f}</text>`).join('');
$('chart').innerHTML=`<svg viewBox="0 0 ${W} ${H}" role="img" aria-label="${rangeLabel(session(),a,b)}的在线人数，点击可定位模拟回放">${grids}<path d="${lines}" fill="none" stroke="#456aeb" stroke-width="2.6" stroke-linecap="round"/><line id="chart-cursor" x1="35" x2="35" y1="8" y2="145" stroke="#94a8ca" stroke-opacity="0.65" stroke-width="1" stroke-dasharray="3 5" pointer-events="none"/><circle id="chart-position-dot" r="4" fill="#456aeb" stroke="white" stroke-width="2" pointer-events="none" visibility="hidden"/>${[a,(a+b)/2,b].map((v,i)=>`<text x="${x(v)}" y="169" text-anchor="${i===0?'start':i===2?'end':'middle'}" fill="#93a0b5" font-size="16">${timeLabel(session(),v)}</text>`).join('')}</svg>`;
const svg=$('chart').firstChild;const locate=e=>{const rect=svg.getBoundingClientRect(),local=(e.clientX-rect.left)/rect.width*W;return Math.max(a,Math.min(b-10,Math.round((a+(local-left)/(right-left)*(b-a))/10)*10));};svg.onmousemove=e=>{const v=locate(e),r=rows.find(r=>r.t===v);$('hover-readout').textContent=`${timeLabel(session(),v)} · ${r?.value==null?'未获取':`${r.value} 人`}`;};svg.onmouseleave=()=>{$('hover-readout').textContent='点击曲线定位回放';};svg.onclick=e=>{cursor=locate(e);playing=false;updateCursor();};}
function updateCursor(){const [a,b]=bounds(),s=session();$('play').textContent=playing?'Ⅱ':'▶';$('play').setAttribute('aria-label',s.source==='anchor-review'?'尚未接入本场录像':playing?'暂停模拟录像':'播放模拟录像');$('play-time').textContent=timeLabel(s,cursor,s.source==='anchor-review');$('play-end').textContent=`/ ${timeLabel(s,b)}`;$('lesson-time').textContent=timeLabel(s,cursor);$('lesson-teacher').textContent=`${s.teacher} · ${s.course}`;const text=transcripts(s,Math.max(0,Math.floor(Math.min(cursor,b-1)/120)*120),Math.min(cursor+120,s.duration))[0];$('lesson-topic').textContent=text?.topic||s.course;$('lesson-line').textContent=text?.text||'课堂片段结束';$('segment-slider').value=cursor;$('video-range').textContent=`当前时段：${rangeLabel(s,a,b)}`;$('back-ten').disabled=cursor<=0;$('forward-ten').disabled=cursor>=s.duration;$('back-ten').textContent=`‹ 后退 ${step/60} 分钟`;$('forward-ten').textContent=`前进 ${step/60} 分钟 ›`;const node=$('chart-cursor');if(node){const x=35+(cursor-a)/(b-a)*550;node.setAttribute('x1',x);node.setAttribute('x2',x);
 const rows=samples(s,a,b),dot=$('chart-position-dot');
 const left=rows.findLast(r=>r.t<=cursor),right=rows.find(r=>r.t>=cursor);
 const valid=left&&right&&left.value!==null&&right.value!==null&&right.t-left.t<=15;
 dot.setAttribute('visibility',valid?'visible':'hidden');
 if(valid){const value=right.t===left.t?left.value:left.value+(right.value-left.value)*(cursor-left.t)/(right.t-left.t);const max=Math.ceil(Math.max(100,...rows.map(r=>r.value??0))/50)*50;dot.setAttribute('cx',x);dot.setAttribute('cy',145-value/max*131);}
 }const buttons=[...$('transcript').querySelectorAll('button')];let active=null;for(const btn of buttons){const on=Number(btn.dataset.t)<=cursor;btn.classList.remove('active');if(on)active=btn;}if(active){active.classList.add('active');const area=$('transcript');if(active.offsetTop-area.offsetTop<area.scrollTop||active.offsetTop-area.offsetTop>area.scrollTop+area.clientHeight-45)area.scrollTop=active.offsetTop-area.offsetTop-30;}}
$('session').onchange=e=>change(()=>{si=Number(e.target.value);top=0;index=null;cursor=0;});$('step').onchange=e=>change(()=>{step=Number(e.target.value);index=0;cursor=top*1800;});$('segment-slider').oninput=e=>seek(Number(e.target.value));$('play').onclick=()=>{const [a,b]=bounds();if(cursor>=b)cursor=a;playing=!playing;lastTick=performance.now();updateCursor();};for(const choice of ['range','session'])$('scope-'+choice).onclick=()=>{persist();scope=choice;edits();};for(const id of ['conclusion','adjustment'])$(id).oninput=()=>{persist();$('save-status').textContent=storageOK?'草稿已暂存 · 点击保存确认复盘':'浏览器存储不可用，内容仅暂存本页';};$('save').onclick=()=>{persist();drafts[noteKey()].savedAt=new Date().toISOString();drafts[key()].savedAt=drafts[noteKey()].savedAt;if(store()){edits();$('toast').textContent='复盘已保存在当前浏览器';$('toast').classList.add('show');setTimeout(()=>$('toast').classList.remove('show'),2300);}};
setInterval(()=>{const now=performance.now();if(playing){cursor=Math.min(bounds()[1],cursor+(now-lastTick)/1000*Number($('speed').value));if(cursor>=bounds()[1])playing=false;updateCursor();}lastTick=now;},200);render();

function seek(target){change(()=>{cursor=Math.max(0,Math.min(target,session().duration));top=Math.min(Math.floor(cursor/1800),Math.ceil(session().duration/1800)-1);index=Math.min(Math.floor((cursor-top*1800)/step),Math.ceil((Math.min((top+1)*1800,session().duration)-top*1800)/step)-1);});}
$('back-ten').onclick=()=>seek(cursor-step);$('forward-ten').onclick=()=>seek(cursor+step);

function updateThemeCount(){$('theme-count').textContent=`${Array.from($('theme').value).length}/16`;}
function saveTheme(){if(themeComposing)return;$('theme').value=limitTheme($('theme').value);updateThemeCount();persist();$('save-status').textContent=storageOK?'主题已暂存 · 点击保存确认复盘':'浏览器存储不可用，主题仅暂存本页';}
let themeComposing=false;$('theme').addEventListener('compositionstart',()=>themeComposing=true);$('theme').addEventListener('compositionend',()=>{themeComposing=false;saveTheme();});$('theme').addEventListener('input',saveTheme);

if(apiSession)setInterval(async()=>{try{const fresh=await loadTestSession();Object.assign(apiSession,fresh);if(session()===apiSession)render();}catch{$('source-note').textContent='后端读取失败，当前显示上次成功数据';}},10000);
